// План specs/android-app.md 1.1 / 1.2 (кейс .qa/tests/android-app/offline/OF-01). Pre-Prod, preprod-ttp (TTP Test Locks), EN. Только чтение.
import { test, expect } from '../../fixtures';
import { OFFLINE_TITLE, ROLE, goOffline, goOnline, offlineBanner, pp, setEnglish } from './offline-helpers';

test.describe('Офлайн — сообщение вместо бесконечной загрузки (#6f8ef9)', () => {
  for (const device of ['@android', '@desktop'] as const) {
    test(`Clients offline shows the "No internet connection" banner; it disappears when back online #6f8ef9 ${device}`, async ({ asUser }) => {
      const page = await asUser(ROLE);
      await setEnglish(page);
      await page.goto(pp('/Customers'));
      await expect(page.getByPlaceholder('Search clients...')).toBeVisible({ timeout: 30_000 });
      await expect(offlineBanner(page)).toHaveCount(0);
      try {
        // Офлайн → полоса (источник: «מה רצוי» — הודעה ברורה במקום טעינה בלי סוף)
        await goOffline(page);
        await expect(offlineBanner(page)).toBeVisible();
        await expect(offlineBanner(page)).toContainText(OFFLINE_TITLE);

        // Онлайн → полоса исчезает (коммент программиста)
        await goOnline(page);
        await expect(offlineBanner(page)).toHaveCount(0);
      } finally {
        await page.context().setOffline(false);
      }
    });
  }
});
